<section class="join-page"><div class="join-page-intro"><span class="eyebrow">START WITH A HELLO</span><h1>FIRST STEP.<br><em>BIG ENERGY.</em></h1><p><?=isset($_GET['sent'])?'Thanks for getting in touch. A friendly face from our team will be in touch soon.':'Tell us a little about what you’re looking for and our club team will help you find your Fitzeno.'?></p><div class="join-contact"><span>CALL US</span><a href="tel:<?=e(preg_replace('/[^0-9+]/','',setting('phone')))?>"><?=e(setting('phone'))?></a><span>COME BY</span><p><?=e(setting('address'))?></p></div></div><form class="join-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><span class="eyebrow">WE’LL BE IN TOUCH</span><label>Your name<input name="name" autocomplete="name" required placeholder="How should we call you?"></label><div class="form-split"><label>Email address<input type="email" name="email" autocomplete="email" required placeholder="you@example.com"></label><label>Phone number<input name="phone" autocomplete="tel" required placeholder="+94"></label></div><label>What are you interested in?<select name="interest"><option value="">Choose one</option><?php foreach(['Membership','Classes','Personal coaching','Club visit','Fitzeno shop','Other'] as $option):?><option <?=isset($_GET['interest'])&&$_GET['interest']===$option?'selected':''?>><?=e($option)?></option><?php endforeach;?></select></label><label>Anything else?<textarea name="message" rows="4" placeholder="Tell us about your goals, timing or questions."></textarea></label><label class="consent"><input type="checkbox" required> I agree to be contacted by the Fitzeno club team.</label><button class="button button-dark" type="submit">SEND MY NOTE ↗</button><small>We’ll only use your details to respond to this enquiry.</small></form></section>
